def list_schemas(project_id, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0076000" if __import__("os").path.isdir("./environment_mix/0076000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(project_id, str) or not re.match(r"^pgproj_[0-9A-Z]{18,}$", project_id or ""):
        return _err("VALIDATION_ERROR", "Invalid project_id.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1:
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1.")
    if cursor is not None and (not isinstance(cursor, str) or not cursor):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")

    projects = _load("projects.json")
    api_keys = _load("api_keys.json")
    catalog = _load("catalog_objects.json")

    proj = next((p for p in projects if p.get("id") == project_id), None)
    if not proj or proj.get("status") != "active":
        return _err("NOT_FOUND", "Project not found or not accessible.")

    # auth: must have an active key for this active project
    key = next((k for k in api_keys if k.get("project_id") == project_id and k.get("status") == "active"), None)
    if not key:
        return _err("UNAUTHORIZED", "No active API key available for this project.")
    perms = key.get("permissions") if isinstance(key.get("permissions"), dict) else {}
    if perms.get("allow_introspection") is not True:
        return _err("UNAUTHORIZED", "API key does not permit introspection.")

    allowed = proj.get("allowed_schemas", None)
    if allowed is not None and (not isinstance(allowed, list) or any(not isinstance(s, str) for s in allowed)):
        return _err("VALIDATION_ERROR", "Project allowed_schemas is invalid in datastore.")

    schemas = set()
    for o in catalog:
        if o.get("project_id") != project_id:
            continue
        if o.get("object_type") != "schema":
            continue
        if o.get("status") != "present":
            continue
        sn = o.get("schema_name")
        if not isinstance(sn, str):
            continue
        if allowed is not None and sn not in allowed:
            continue
        schemas.add(sn)

    items = sorted(schemas)

    # cursor is opaque: base64url of integer offset
    offset = 0
    if cursor is not None:
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("ascii")).decode("utf-8")
            if not raw.startswith("off:"):
                return _err("VALIDATION_ERROR", "Malformed cursor.")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                return _err("VALIDATION_ERROR", "Malformed cursor.")
        except Exception:
            return _err("VALIDATION_ERROR", "Malformed cursor.")

    page = items[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < len(items)
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"off:{next_off}".encode("utf-8")).decode("ascii").rstrip("=")

    # update last_used_at for read too (usage dynamics) + persist
    key["last_used_at"] = now
    key["updated_at"] = now
    _save("api_keys.json", api_keys)

    return {
        "schemas": page,
        "total": len(items),
        "limit": limit,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "latency_ms": int((time.time() - t0) * 1000)
    }

def list_tables(project_id, schema=None, include_views=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0076000" if __import__("os").path.isdir("./environment_mix/0076000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    if not isinstance(project_id, str) or not re.match(r"^pgproj_[0-9A-Z]{18,}$", project_id or ""):
        return _err("VALIDATION_ERROR", "Invalid project_id.")
    if schema is None:
        schema = "public"
    if not isinstance(schema, str) or not schema.strip():
        return _err("VALIDATION_ERROR", "schema must be a non-empty string when provided.")
    if include_views is None:
        include_views = False
    if not isinstance(include_views, bool):
        return _err("VALIDATION_ERROR", "include_views must be a boolean when provided.")
    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1:
        return _err("VALIDATION_ERROR", "limit must be an integer >= 1.")
    if cursor is not None and (not isinstance(cursor, str) or not cursor):
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided.")

    projects = _load("projects.json")
    api_keys = _load("api_keys.json")
    catalog = _load("catalog_objects.json")

    proj = next((p for p in projects if p.get("id") == project_id), None)
    if not proj or proj.get("status") != "active":
        return _err("NOT_FOUND", "Project not found or not accessible.")

    key = next((k for k in api_keys if k.get("project_id") == project_id and k.get("status") == "active"), None)
    if not key:
        return _err("UNAUTHORIZED", "No active API key available for this project.")
    perms = key.get("permissions") if isinstance(key.get("permissions"), dict) else {}
    if perms.get("allow_introspection") is not True:
        return _err("UNAUTHORIZED", "API key does not permit introspection.")

    allowed = proj.get("allowed_schemas", None)
    if allowed is not None:
        if not isinstance(allowed, list) or any(not isinstance(s, str) for s in allowed):
            return _err("VALIDATION_ERROR", "Project allowed_schemas is invalid in datastore.")
        if schema not in allowed:
            return _err("UNAUTHORIZED", "Schema not allowed for this project.")

    types = ["table"]
    if include_views:
        types += ["view", "materialized_view"]

    objs = []
    for o in catalog:
        if o.get("project_id") != project_id:
            continue
        if o.get("status") != "present":
            continue
        if o.get("schema_name") != schema:
            continue
        if o.get("object_type") not in types:
            continue
        objs.append({
            "id": o.get("id"),
            "schema_name": o.get("schema_name"),
            "object_type": o.get("object_type"),
            "name": o.get("object_name"),
            "comment": o.get("comment"),
            "source_refreshed_at": o.get("source_refreshed_at")
        })

    objs.sort(key=lambda x: ((x.get("object_type") or ""), (x.get("name") or "")))

    offset = 0
    if cursor is not None:
        try:
            pad = "=" * (-len(cursor) % 4)
            raw = base64.urlsafe_b64decode((cursor + pad).encode("ascii")).decode("utf-8")
            if not raw.startswith("off:"):
                return _err("VALIDATION_ERROR", "Malformed cursor.")
            offset = int(raw.split(":", 1)[1])
            if offset < 0:
                return _err("VALIDATION_ERROR", "Malformed cursor.")
        except Exception:
            return _err("VALIDATION_ERROR", "Malformed cursor.")

    page = objs[offset:offset + limit]
    next_off = offset + len(page)
    has_more = next_off < len(objs)
    next_cursor = None
    if has_more:
        next_cursor = base64.urlsafe_b64encode(f"off:{next_off}".encode("utf-8")).decode("ascii").rstrip("=")

    key["last_used_at"] = now
    key["updated_at"] = now
    _save("api_keys.json", api_keys)

    return {
        "objects": page,
        "total": len(objs),
        "limit": limit,
        "cursor": cursor,
        "has_more": has_more,
        "next_cursor": next_cursor,
        "latency_ms": int((time.time() - t0) * 1000)
    }

def describe_table(project_id, table_name, schema=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0076000" if __import__("os").path.isdir("./environment_mix/0076000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _logs_list_container():
        raw = _load("request_logs.json")
        if isinstance(raw, dict):
            if isinstance(raw.get("rows"), list):
                return raw, raw["rows"]
            # tolerate dict without rows
            raw["rows"] = []
            return raw, raw["rows"]
        if isinstance(raw, list):
            return None, raw
        return None, []

    def _write_log(status, api_key_id=None, error_code=None, extra=None):
        container, rows = _logs_list_container()
        row = {
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "describe_table",
            "tool": "describe_table",
            "project_id": project_id if isinstance(project_id, str) else None,
            "api_key_id": api_key_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "timestamp": now,
        }
        if isinstance(extra, dict):
            row.update(extra)
        rows.append(row)
        _save("request_logs.json", container if container is not None else rows)

    # Validate inputs
    if not isinstance(project_id, str) or not project_id.strip():
        _write_log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is required and must be a non-empty string.", field="project_id")
    project_id = project_id.strip()
    if not re.match(r"^pgproj_[0-9A-Z]{18,}$", project_id):
        _write_log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid project_id.", field="project_id")

    if not isinstance(table_name, str) or not table_name.strip():
        _write_log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "table_name is required and must be a non-empty string.", field="table_name")
    table_name = table_name.strip()

    if schema is None:
        schema = "public"
    if not isinstance(schema, str) or not schema.strip():
        _write_log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "schema must be a non-empty string when provided.", field="schema")
    schema = schema.strip()

    # Load project
    projects = _load("projects.json")
    if isinstance(projects, dict) and isinstance(projects.get("rows"), list):
        projects = projects["rows"]
    if not isinstance(projects, list):
        projects = []
    project = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not project:
        _write_log("error", None, "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)
    if project.get("status") != "active":
        _write_log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Project is not active.", project_id=project_id, status=project.get("status"))

    # Ambient auth resolution: must find an active key scoped to this project with introspection permission.
    api_keys = _load("api_keys.json")
    if isinstance(api_keys, dict) and isinstance(api_keys.get("rows"), list):
        api_keys = api_keys["rows"]
    if not isinstance(api_keys, list):
        api_keys = []
    usable_keys = []
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("project_id") != project_id:
            continue
        if k.get("status") != "active":
            continue
        perms = k.get("permissions") if isinstance(k.get("permissions"), dict) else {}
        if perms.get("allow_introspection") is True:
            usable_keys.append(k)
    if not usable_keys:
        _write_log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key with allow_introspection=true is available for this project.", project_id=project_id)

    api_key = usable_keys[0]
    api_key_id = api_key.get("id")

    # Visibility: if allowed_schemas is an allowlist, filter results, but do NOT error if filtered; return NOT_FOUND only if object absent.
    allowed = project.get("allowed_schemas", None)
    schema_visible = True
    if allowed is not None:
        if isinstance(allowed, list):
            schema_visible = schema in allowed
        else:
            # if corrupt type, treat as all allowed (most permissive)
            schema_visible = True

    catalog = _load("catalog_objects.json")
    if isinstance(catalog, dict) and isinstance(catalog.get("rows"), list):
        catalog = catalog["rows"]
    if not isinstance(catalog, list):
        catalog = []

    # Find table/view/matview
    table_obj = None
    for o in catalog:
        if not isinstance(o, dict):
            continue
        if o.get("project_id") != project_id:
            continue
        if o.get("status") != "present":
            continue
        if o.get("schema_name") != schema:
            continue
        if o.get("object_type") not in ("table", "view", "materialized_view"):
            continue
        if o.get("object_name") != table_name:
            continue
        table_obj = o
        break

    # Update last_used_at regardless of outcome (success/failure) per business rule pattern.
    api_key["last_used_at"] = now
    api_key["updated_at"] = now
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == api_key_id:
            api_keys[i] = api_key
            break
    _save("api_keys.json", api_keys)

    if not schema_visible:
        # Real APIs typically behave like NOT_FOUND for filtered resources.
        _write_log("ok", api_key_id, None, extra={"filtered_by_allowed_schemas": True})
        return {"project_id": project_id, "schema": schema, "table_name": table_name, "table": None, "columns": []}

    if not table_obj:
        _write_log("ok", api_key_id, None)
        return {"project_id": project_id, "schema": schema, "table_name": table_name, "table": None, "columns": []}

    # Collect columns
    cols = []
    parent_id = table_obj.get("id")
    for o in catalog:
        if not isinstance(o, dict):
            continue
        if o.get("project_id") != project_id:
            continue
        if o.get("status") != "present":
            continue
        if o.get("object_type") != "column":
            continue
        if o.get("parent_object_id") != parent_id:
            continue
        cols.append(o)

    def _ord(v):
        try:
            return int(v)
        except Exception:
            return 10**9

    cols.sort(key=lambda r: (_ord(r.get("ordinal_position")), str(r.get("object_name") or "")))

    _write_log("ok", api_key_id, None, extra={"table_object_id": parent_id, "column_count": len(cols)})
    return {
        "project_id": project_id,
        "schema": schema,
        "table_name": table_name,
        "table": table_obj,
        "columns": cols,
    }

