        return _err("VALIDATION_ERROR", "Invalid project_id.", field="project_id")

    if not isinstance(table_name, str) or not table_name.strip():
        _write_log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "table_name is required and must be a non-empty string.", field="table_name")
    table_name = table_name.strip()

    if schema is None:
        schema = "public"
    if not isinstance(schema, str) or not schema.strip():
        _write_log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "schema must be a non-empty string when provided.", field="schema")
    schema = schema.strip()

    projects = _load("projects.json")
    if isinstance(projects, dict) and isinstance(projects.get("rows"), list):
        projects = projects["rows"]
    if not isinstance(projects, list):
        projects = []
    project = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not project:
        _write_log("error", None, "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)
    if project.get("status") != "active":
        _write_log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Project is not active.", project_id=project_id, status=project.get("status"))

    api_keys = _load("api_keys.json")
    if isinstance(api_keys, dict) and isinstance(api_keys.get("rows"), list):
        api_keys = api_keys["rows"]
    if not isinstance(api_keys, list):
        api_keys = []
    usable_keys = []
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("project_id") != project_id:
            continue
        if k.get("status") != "active":
            continue
        perms = k.get("permissions") if isinstance(k.get("permissions"), dict) else {}
        if perms.get("allow_introspection") is True:
            usable_keys.append(k)
    if not usable_keys:
        _write_log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key with allow_introspection=true is available for this project.", project_id=project_id)
    api_key = usable_keys[0]
    api_key_id = api_key.get("id")

    # Update last_used_at
    api_key["last_used_at"] = now
    api_key["updated_at"] = now
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == api_key_id:
            api_keys[i] = api_key
            break
    _save("api_keys.json", api_keys)

    allowed = project.get("allowed_schemas", None)
    def _schema_allowed(s):
        if allowed is None:
            return True
        if isinstance(allowed, list):
            return s in allowed
        return True

    # If schema is filtered, return empty rather than error.
    if not _schema_allowed(schema):
        _write_log("ok", api_key_id, None, extra={"filtered_by_allowed_schemas": True})
        return {
            "project_id": project_id,
            "schema": schema,
            "table_name": table_name,
            "explicit_relationships": [],
            "implied_relationships": [],
        }

    catalog = _load("catalog_objects.json")
    if isinstance(catalog, dict) and isinstance(catalog.get("rows"), list):
        catalog = catalog["rows"]
    if not isinstance(catalog, list):
        catalog = []

    # Locate the table object and its columns
    table_obj = None
    for o in catalog:
        if not isinstance(o, dict):
            continue
        if o.get("project_id") != project_id:
            continue
        if o.get("status") != "present":
            continue
        if o.get("schema_name") != schema:
            continue
        if o.get("object_type") not in ("table", "view", "materialized_view"):
            continue
        if o.get("object_name") == table_name:
            table_obj = o
            break

    if not table_obj:
        _write_log("ok", api_key_id, None, extra={"table_found": False})
        return {
            "project_id": project_id,
            "schema": schema,
            "table_name": table_name,
            "explicit_relationships": [],
            "implied_relationships": [],
        }

    table_id = table_obj.get("id")
    cols = []
    for o in catalog:
        if not isinstance(o, dict):
            continue
        if o.get("project_id") != project_id:
            continue
        if o.get("status") != "present":
            continue
        if o.get("object_type") != "column":
            continue
        if o.get("parent_object_id") != table_id:
            continue
        cols.append(o)

    # Explicit relationships: FKs where table is referencing or referenced
    fks = _load("foreign_keys.json")
    if isinstance(fks, dict) and isinstance(fks.get("rows"), list):
        fks = fks["rows"]
    if not isinstance(fks, list):
        fks = []

    explicit = []
    for fk in fks:
        if not isinstance(fk, dict):
            continue
        if fk.get("project_id") != project_id:
            continue
        if fk.get("status") != "present":
            continue
        # Respect allowed_schemas on both sides
        if not _schema_allowed(fk.get("schema_name")):
            continue
        if not _schema_allowed(fk.get("referenced_schema_name")):
            continue
        if (fk.get("schema_name") == schema and fk.get("table_name") == table_name) or (
            fk.get("referenced_schema_name") == schema and fk.get("referenced_table_name") == table_name
        ):
            explicit.append(fk)

    # Implied relationships: column *_id implies referenced table named * with pk id/(*_id)
    # Only if both tables/columns exist and present and within allowed_schemas.
    present_tables = {}  # (schema, name) -> object
    present_columns = {}  # (parent_id, column_name) -> column obj
    for o in catalog:
        if not isinstance(o, dict):
            continue
        if o.get("project_id") != project_id or o.get("status") != "present":
            continue
        if o.get("object_type") in ("table", "view", "materialized_view"):
            if _schema_allowed(o.get("schema_name")):
                present_tables[(o.get("schema_name"), o.get("object_name"))] = o
        elif o.get("object_type") == "column":
            present_columns[(o.get("parent_object_id"), o.get("object_name"))] = o

    implied = []
    for c in cols:
        cn = c.get("object_name") or ""
        if not isinstance(cn, str):
            continue
        if not cn.endswith("_id"):
            continue
        base = cn[:-3]
        # candidate tables: base, base+"s"
        candidates = [(schema, base), (schema, base + "s")]
        for sch, tname in candidates:
            tgt = present_tables.get((sch, tname))
            if not tgt:
                continue
            tgt_id = tgt.get("id")
            # pk column conventions: 'id' or f'{singular}_id' (i.e., base+'_id')
            pk_names = ["id", base + "_id"]
            pk_col = None
            for pk in pk_names:
                col_obj = present_columns.get((tgt_id, pk))
                if col_obj:
                    pk_col = col_obj
                    break
            if not pk_col:
                continue
            implied.append(
                {
                    "type": "implied",
                    "from": {"schema": schema, "table": table_name, "column": cn},
                    "to": {"schema": sch, "table": tname, "column": pk_col.get("object_name")},
                    "confidence": "low",
                    "reason": "column_name_pattern",
                }
            )
            break  # first match per column

    _write_log("ok", api_key_id, None, extra={"explicit_count": len(explicit), "implied_count": len(implied)})
    return {
        "project_id": project_id,
        "schema": schema,
        "table_name": table_name,
        "explicit_relationships": explicit,
        "implied_relationships": implied,
    }

def get_query_job(project_id, query_job_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0076000" if __import__("os").path.isdir("./environment_mix/0076000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _logs_list_container():
        raw = _load("request_logs.json")
        if isinstance(raw, dict):
            if isinstance(raw.get("rows"), list):
                return raw, raw["rows"]
            raw["rows"] = []
            return raw, raw["rows"]
        if isinstance(raw, list):
            return None, raw
        return None, []

    def _write_log(status, api_key_id=None, error_code=None, extra=None):
        container, rows = _logs_list_container()
        row = {
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "get_query_job",
            "tool": "get_query_job",
            "project_id": project_id if isinstance(project_id, str) else None,
            "api_key_id": api_key_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "timestamp": now,
        }
        if isinstance(extra, dict):
            row.update(extra)
        rows.append(row)
        _save("request_logs.json", container if container is not None else rows)

    # ---- validate inputs (relaxed to accept actual store ids / prior buggy callers) ----
    if not isinstance(project_id, str) or not project_id.strip():
        _write_log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is required and must be a non-empty string.", field="project_id")
    if not isinstance(query_job_id, str) or not query_job_id.strip():
        _write_log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query_job_id is required and must be a non-empty string.", field="query_job_id")

    project_id = project_id.strip()
    query_job_id = query_job_id.strip()

    if not re.match(r"^pgproj_[0-9A-Z]{18,}$", project_id):
        _write_log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid project_id.", field="project_id")

    # Real API expects pgjob_* but do not hard-reject if caller passes an id that exists.
    strict_job_pattern_ok = bool(re.match(r"^pgjob_[0-9A-Z]{18,}$", query_job_id))

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    query_jobs = _load("query_jobs.json")
    if not isinstance(query_jobs, list):
        query_jobs = []

    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not proj:
        _write_log("error", None, "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)

    if proj.get("status") != "active":
        _write_log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Project is not active.", project_id=project_id, status=proj.get("status"))

    # AUTH (ambient): find any active key scoped to this active project that permits reading jobs.
    # Tool description says "lacks introspection permission" -> treat allow_introspection as required.
    usable_key = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        if k.get("project_id") != project_id:
            continue
        perms = k.get("permissions") if isinstance(k.get("permissions"), dict) else {}
        if perms.get("allow_introspection") is True:
            usable_key = k
            break
    if usable_key is None:
        _write_log("error", None, "UNAUTHORIZED")
        return _err(
            "UNAUTHORIZED",
            "No active API key with allow_introspection=true is available for this project.",
            project_id=project_id,
        )

    # Fetch job: if strict pattern fails, still allow fetching by id if it exists.
    job = next((j for j in query_jobs if isinstance(j, dict) and j.get("id") == query_job_id and j.get("project_id") == project_id), None)

    if job is None and not strict_job_pattern_ok:
        # If caller passed a project id in query_job_id (as in audit defect), return NOT_FOUND not VALIDATION_ERROR.
        _write_log("error", usable_key.get("id"), "NOT_FOUND")
        return _err("NOT_FOUND", "Query job not found.", project_id=project_id, query_job_id=query_job_id)

    if job is None:
        _write_log("error", usable_key.get("id"), "NOT_FOUND")
        return _err("NOT_FOUND", "Query job not found.", project_id=project_id, query_job_id=query_job_id)

    # Visibility: jobs can be created with api_key_id NULL (no-auth mode); otherwise ensure scoped to this project.
    # With ambient auth, we allow viewing any job within the project.
    # Truncate returned result_rows to caller/server limits (best-effort; stored rows may already be truncated).
    max_rows = usable_key.get("max_rows_per_query")
    if max_rows is None:
        max_rows = 10000
    try:
        max_rows = int(max_rows)
    except Exception:
        max_rows = 10000
    if max_rows < 1:
        max_rows = 1
    if max_rows > 100000:
        max_rows = 100000
    hard_cap = 100000
    cap = min(max_rows, hard_cap)

    result = dict(job)
    if result.get("result_format") == "json_rows":
        rows = result.get("result_rows")
        if isinstance(rows, list) and len(rows) > cap:
            result["result_rows"] = rows[:cap]
    else:
        # Enforce constraint: result_format='none' implies result_rows is null
        result["result_rows"] = None

    # Update key last_used_at (read counts as usage) and persist.
    key_id = usable_key.get("id")
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_id:
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    _write_log("ok", key_id, None, extra={"query_job_id": query_job_id})
    return {"data": result}

def list_query_jobs(project_id, status=None, schema_name=None, statement_type=None, created_after=None, created_before=None, limit=None, cursor=None, **_extra):
    import json, os, datetime, re, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0076000" if __import__("os").path.isdir("./environment_mix/0076000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    VALID_STATUS = {"queued", "running", "succeeded", "failed", "cancelled"}
    VALID_STMT = {"select", "insert", "update", "delete", "ddl", "transaction", "other"}

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                return datetime.datetime.fromisoformat(s[:-1])
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _log(status_s, api_key_id=None, error_code=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append({
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "tool": "list_query_jobs",
            "project_id": project_id if isinstance(project_id, str) else None,
            "api_key_id": api_key_id,
            "status": status_s,
            "error_code": error_code,
            "timestamp": now,
            "latency_ms": int((time.time() - t0) * 1000),
        })
        _save("request_logs.json", logs)

    def _resolve_auth_for_project(pid):
        projects = _load("projects.json")
        api_keys = _load("api_keys.json")

        proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == pid), None)
        if not proj or proj.get("status") != "active":
            return None, None, _err("NOT_FOUND", "Project not found or not active.", project_id=pid)

        usable = []
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("project_id") != pid:
                continue
            if k.get("status") != "active":
                continue
            perms = k.get("permissions") if isinstance(k.get("permissions"), dict) else {}
            # Viewing query history requires introspection or query permission.
            if perms.get("allow_introspection") is True or perms.get("allow_query") is True:
                usable.append(k)
        if not usable:
            return proj, None, _err("UNAUTHORIZED", "No active API key available for this project with required permissions.")
        # choose stable key
        usable.sort(key=lambda x: (x.get("last_used_at") or "", x.get("created_at") or ""), reverse=True)
        return proj, usable[0], None

    def _decode_cursor(cur):
        if cur is None:
            return None
        if not isinstance(cur, str) or not cur.strip():
            return "bad"
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            obj = json.loads(raw.decode("utf-8"))
            if not isinstance(obj, dict):
                return "bad"
            # expect {"created_at": "...", "id": "..."}
            if "created_at" not in obj or "id" not in obj:
                return "bad"
            dt = _parse_rfc3339(obj["created_at"])
            if dt is None or not isinstance(obj["id"], str):
                return "bad"
            return {"created_at": obj["created_at"], "id": obj["id"]}
        except Exception:
            return "bad"

    def _encode_cursor(created_at_s, id_s):
        payload = json.dumps({"created_at": created_at_s, "id": id_s}, ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    # validate
    if not isinstance(project_id, str) or not re.match(r"^pgproj_[0-9A-Z]{18,}$", project_id or ""):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid project_id.", field="project_id")
    if status is not None:
        if not isinstance(status, str) or status not in VALID_STATUS:
            _log("error", None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status.", field="status", allowed=sorted(VALID_STATUS))
    if schema_name is not None and (not isinstance(schema_name, str) or not schema_name.strip()):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "schema_name must be a non-empty string when provided.", field="schema_name")
    if statement_type is not None:
        if not isinstance(statement_type, str) or statement_type not in VALID_STMT:
            _log("error", None, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid statement_type.", field="statement_type", allowed=sorted(VALID_STMT))
    ca = _parse_rfc3339(created_after) if created_after is not None else None
    if created_after is not None and ca is None:
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "created_after must be RFC3339 date-time.", field="created_after")
    cb = _parse_rfc3339(created_before) if created_before is not None else None
    if created_before is not None and cb is None:
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "created_before must be RFC3339 date-time.", field="created_before")
    if ca and cb and ca > cb:
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "created_after must be <= created_before.")
    if limit is None:
        limit = 50
    if not isinstance(limit, int) or not (1 <= limit <= 200):
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200.", field="limit")

    curv = _decode_cursor(cursor)
    if curv == "bad":
        _log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Malformed cursor.", field="cursor")

    proj, api_key, auth_err = _resolve_auth_for_project(project_id)
    if auth_err:
        _log("error", api_key.get("id") if isinstance(api_key, dict) else None, auth_err["error"]["code"])
        return auth_err

    jobs = _load("query_jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    # filter by project
    filt = [j for j in jobs if isinstance(j, dict) and j.get("project_id") == project_id]

    if status is not None:
        filt = [j for j in filt if j.get("status") == status]
    if schema_name is not None:
        sn = schema_name.strip()
        filt = [j for j in filt if j.get("schema_name") == sn]
    if statement_type is not None:
        filt = [j for j in filt if j.get("statement_type") == statement_type]
    if ca is not None:
        def ok_after(j):
            dt = _parse_rfc3339(j.get("created_at"))
            return dt is not None and dt >= ca
        filt = [j for j in filt if ok_after(j)]
    if cb is not None:
        def ok_before(j):
            dt = _parse_rfc3339(j.get("created_at"))
            return dt is not None and dt < cb
        filt = [j for j in filt if ok_before(j)]

    # sort reverse-chronological by created_at then id
    def _sort_key(j):
        dt = _parse_rfc3339(j.get("created_at"))
        return (dt or datetime.datetime.min, j.get("id") or "")
    filt.sort(key=_sort_key, reverse=True)

    # apply cursor: return items strictly older than cursor position (created_at,id) in sort order
    if isinstance(curv, dict):
        cur_dt = _parse_rfc3339(curv["created_at"])
        cur_id = curv["id"]
        def _is_after_or_equal(j):
            dt = _parse_rfc3339(j.get("created_at"))
            jid = j.get("id")
            if dt is None or jid is None:
                return False
            if dt > cur_dt:
                return True
            if dt == cur_dt and str(jid) >= str(cur_id):
                return True
            return False
        filt = [j for j in filt if not _is_after_or_equal(j)]

    total = len(filt)
    page = filt[:limit]
    has_more = total > len(page)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _encode_cursor(last.get("created_at"), last.get("id"))

    # Update last_used_at
    api_keys = _load("api_keys.json")
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    _log("ok", api_key.get("id"), None)
    return {
        "data": page,
        "meta": {
            "project_id": project_id,
            "total": total,
            "limit": limit,
            "has_more": has_more,
            "next_cursor": next_cursor,
        }
    }

def cancel_query_job(project_id, query_job_id, **_extra):
    import json, os, datetime, time, re
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0076000" if __import__("os").path.isdir("./environment_mix/0076000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.utcnow().replace(microsecond=0)
    now = now_dt.isoformat() + "Z"

    def _logs_list_container():
        raw = _load("request_logs.json")
        if isinstance(raw, dict):
            if isinstance(raw.get("rows"), list):
                return raw, raw["rows"]
            raw["rows"] = []
            return raw, raw["rows"]
        if isinstance(raw, list):
            return None, raw
        return None, []

    def _write_log(status, api_key_id=None, error_code=None, extra=None):
        container, rows = _logs_list_container()
        row = {
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "cancel_query_job",
            "tool": "cancel_query_job",
            "project_id": project_id if isinstance(project_id, str) else None,
            "api_key_id": api_key_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
            "created_at": now,
            "timestamp": now,
        }
        if isinstance(extra, dict):
            row.update(extra)
        rows.append(row)
        _save("request_logs.json", container if container is not None else rows)

    # ---- validate inputs (relaxed for actual store ids / prior buggy callers) ----
    if not isinstance(project_id, str) or not project_id.strip():
        _write_log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "project_id is required and must be a non-empty string.", field="project_id")
    if not isinstance(query_job_id, str) or not query_job_id.strip():
        _write_log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query_job_id is required and must be a non-empty string.", field="query_job_id")

    project_id = project_id.strip()
    query_job_id = query_job_id.strip()

    if not re.match(r"^pgproj_[0-9A-Z]{18,}$", project_id):
        _write_log("error", None, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid project_id.", field="project_id")

    strict_job_pattern_ok = bool(re.match(r"^pgjob_[0-9A-Z]{18,}$", query_job_id))

    projects = _load("projects.json")
    if not isinstance(projects, list):
        projects = []
    api_keys = _load("api_keys.json")
    if not isinstance(api_keys, list):
        api_keys = []
    query_jobs = _load("query_jobs.json")
    if not isinstance(query_jobs, list):
        query_jobs = []

    proj = next((p for p in projects if isinstance(p, dict) and p.get("id") == project_id), None)
    if not proj:
        _write_log("error", None, "NOT_FOUND")
        return _err("NOT_FOUND", "Project not found.", project_id=project_id)
    if proj.get("status") != "active":
        _write_log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Project is not active.", project_id=project_id, status=proj.get("status"))

    # AUTH (ambient): require an active key for the project that permits managing jobs.
    # Schema doesn't define explicit manage permission; use allow_query or allow_write as a proxy.
    usable_key = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        if k.get("project_id") != project_id:
            continue
        perms = k.get("permissions") if isinstance(k.get("permissions"), dict) else {}
        if perms.get("allow_query") is True or perms.get("allow_write") is True:
            usable_key = k
            break
    if usable_key is None:
        _write_log("error", None, "UNAUTHORIZED")
        return _err(
            "UNAUTHORIZED",
            "No active API key with sufficient permissions (allow_query or allow_write) is available for this project.",
            project_id=project_id,
        )

    # Locate the job
    job_idx = None
    for i, j in enumerate(query_jobs):
        if isinstance(j, dict) and j.get("id") == query_job_id and j.get("project_id") == project_id:
            job_idx = i
            break

    if job_idx is None and not strict_job_pattern_ok:
        _write_log("error", usable_key.get("id"), "NOT_FOUND")
        return _err("NOT_FOUND", "Query job not found.", project_id=project_id, query_job_id=query_job_id)

    if job_idx is None:
        _write_log("error", usable_key.get("id"), "NOT_FOUND")
        return _err("NOT_FOUND", "Query job not found.", project_id=project_id, query_job_id=query_job_id)

    job = query_jobs[job_idx]

    terminal = {"succeeded", "failed", "cancelled"}
    if job.get("status") in terminal:
        _write_log("error", usable_key.get("id"), "CONFLICT", extra={"query_job_id": query_job_id})
        return _err(
            "CONFLICT",
            "Cannot cancel a terminal query job.",
            project_id=project_id,
            query_job_id=query_job_id,
            status=job.get("status"),
        )

    if job.get("status") not in ("queued", "running"):
        _write_log("error", usable_key.get("id"), "INVALID_TRANSITION", extra={"query_job_id": query_job_id})
        return _err(
            "INVALID_TRANSITION",
            "Query job status cannot transition to cancelled from the current state.",
            project_id=project_id,
            query_job_id=query_job_id,
            from_status=job.get("status"),
            to_status="cancelled",
        )

    # Apply lifecycle transition
    updated = dict(job)
    updated["status"] = "cancelled"
    updated["finished_at"] = now
    if updated.get("started_at") and not updated.get("duration_ms"):
        # best-effort duration: compute if timestamps parse; otherwise leave null
        try:
            # parse isoformat with Z
            def _parse(ts):
                if not isinstance(ts, str):
                    return None
                if ts.endswith("Z"):
                    ts = ts[:-1]
                # allow fractional seconds
                return datetime.datetime.fromisoformat(ts)
            st = _parse(updated.get("started_at"))
            ft = _parse(now)
            if st and ft:
                dm = int(max(0, (ft - st).total_seconds() * 1000))
                updated["duration_ms"] = dm
        except Exception:
            pass
    updated["updated_at"] = now

    # Enforce constraint: terminal status implies finished_at not null (we set it)
    query_jobs[job_idx] = updated
    _save("query_jobs.json", query_jobs)

    # Update key last_used_at and persist
    key_id = usable_key.get("id")
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == key_id:
            k["last_used_at"] = now
            k["updated_at"] = now
            break
    _save("api_keys.json", api_keys)

    _write_log("ok", key_id, None, extra={"query_job_id": query_job_id})
    return {"data": updated}

def refresh_catalog(project_id, schema_names=None, force=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0076000" if __import__("os").path.isdir("./environment_mix/0076000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- Validation
    if not isinstance(project_id, str) or not re.match(r"^pgproj_[0-9A-Z]{18,}$", project_id):
        return _err("VALIDATION_ERROR", "Invalid project_id.")
    if schema_names is not None:
        if not isinstance(schema_names, list) or any(not isinstance(s, str) or not s for s in schema_names):
            return _err("VALIDATION_ERROR", "schema_names must be an array of non-empty strings.")
    if force is not None and not isinstance(force, bool):
        return _err("VALIDATION_ERROR", "force must be a boolean.")

    projects = _load("projects.json")
    api_keys = _load("api_keys.json")
    catalog_objects = _load("catalog_objects.json")
    foreign_keys = _load("foreign_keys.json")
    request_logs = _load("request_logs.json")

    def _log(status, api_key_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        request_logs.append({
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "refresh_catalog",
            "project_id": project_id,
            "api_key_id": api_key_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("request_logs.json", request_logs)

    # --- Auth: active api_keys scoped to active project with allow_introspection
    proj = next((p for p in projects if p.get("id") == project_id), None)
    if not proj or proj.get("status") != "active":
        _log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Project is not active or does not exist.")

    usable_key = None
    for k in api_keys:
        if k.get("project_id") != project_id or k.get("status") != "active":
            continue
        perms = k.get("permissions") or {}
        if perms.get("allow_introspection") is True:
            usable_key = k
            break
    if not usable_key:
        _log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key is authorized to introspect this project.")

    allowed = proj.get("allowed_schemas", None)  # may be None
    # Determine refresh scope
    if schema_names is None:
        if allowed is None:
            scope = None  # all visible
        else:
            scope = list(dict.fromkeys([s for s in allowed if isinstance(s, str) and s]))
    else:
        # enforce allowed_schemas
        if allowed is not None:
            not_allowed = [s for s in schema_names if s not in allowed]
            if not_allowed:
                _log("error", usable_key.get("id"), "UNAUTHORIZED")
                return _err("UNAUTHORIZED", "One or more schemas are not visible under allowed_schemas.", schema_names=not_allowed)
        scope = list(dict.fromkeys(schema_names))

    # Since offline datastore cannot actually query PostgreSQL catalogs, we implement idempotent "mark refreshed"
    # and "mark dropped for missing from snapshot" behavior relative to a provided/known snapshot.
    #
    # Real refresh would upsert from source snapshot; here we treat current cache as the snapshot.
    # If force==True, we still update source_refreshed_at/updated_at for rows in scope.
    #
    # Idempotency: repeated refresh produces same set, only timestamps move when force true.
    touched_obj = 0
    touched_fk = 0

    def _in_scope(schema):
        if scope is None:
            # all visible under allowed_schemas (allowed None => all; allowed list => only those)
            if allowed is None:
                return True
            return schema in allowed
        return schema in scope

    # Update source_refreshed_at for present objects in scope
    for o in catalog_objects:
        if o.get("project_id") != project_id:
            continue
        sname = o.get("schema_name")
        if not isinstance(sname, str):
            continue
        if not _in_scope(sname):
            continue
        if o.get("status") == "present":
            # mark refreshed
            if force or o.get("source_refreshed_at") != now:
                o["source_refreshed_at"] = now
                o["updated_at"] = now
                touched_obj += 1

    for fk in foreign_keys:
        if fk.get("project_id") != project_id:
            continue
        sname = fk.get("schema_name")
        if not isinstance(sname, str):
            continue
        if not _in_scope(sname):
            continue
        if fk.get("status") == "present":
            if force or fk.get("source_refreshed_at") != now:
                fk["source_refreshed_at"] = now
                fk["updated_at"] = now
                touched_fk += 1

    # Persist mutations (only if any effect, to avoid false success)
    if touched_obj == 0 and touched_fk == 0 and not force:
        # still log the call; considered ok but with no changes because already fresh in this offline model
        usable_key["last_used_at"] = now
        usable_key["updated_at"] = now
        _save("api_keys.json", api_keys)
        _log("ok", usable_key.get("id"), None)
        return {
            "acknowledged": True,
            "project_id": project_id,
            "refreshed_schemas": scope if scope is not None else ("ALL" if allowed is None else list(allowed)),
            "force": bool(force) if force is not None else False,
            "catalog_objects_updated": 0,
            "foreign_keys_updated": 0
        }

    _save("catalog_objects.json", catalog_objects)
    _save("foreign_keys.json", foreign_keys)

    usable_key["last_used_at"] = now
    usable_key["updated_at"] = now
    _save("api_keys.json", api_keys)

    _log("ok", usable_key.get("id"), None)
    return {
        "acknowledged": True,
        "project_id": project_id,
        "refreshed_schemas": scope if scope is not None else ("ALL" if allowed is None else list(allowed)),
        "force": bool(force) if force is not None else False,
        "catalog_objects_updated": touched_obj,
        "foreign_keys_updated": touched_fk
    }

def get_catalog_object(project_id, schema_name, object_type, object_name, parent_object_id=None, include_dropped=None, **_extra):
    import json, os, datetime, re, time
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0076000" if __import__("os").path.isdir("./environment_mix/0076000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # --- Validation
    if not isinstance(project_id, str) or not re.match(r"^pgproj_[0-9A-Z]{18,}$", project_id):
        return _err("VALIDATION_ERROR", "Invalid project_id.")
    if not isinstance(schema_name, str) or not schema_name:
        return _err("VALIDATION_ERROR", "schema_name must be a non-empty string.")
    if object_type not in ("schema", "table", "view", "materialized_view", "column"):
        return _err("VALIDATION_ERROR", "Invalid object_type.")
    if not isinstance(object_name, str) or not object_name:
        return _err("VALIDATION_ERROR", "object_name must be a non-empty string.")
    if parent_object_id is not None:
        if not isinstance(parent_object_id, str) or not re.match(r"^pgcat_[0-9A-Z]{18,}$", parent_object_id):
            return _err("VALIDATION_ERROR", "Invalid parent_object_id.")
    if include_dropped is not None and not isinstance(include_dropped, bool):
        return _err("VALIDATION_ERROR", "include_dropped must be a boolean.")
    include_dropped = bool(include_dropped) if include_dropped is not None else False

    projects = _load("projects.json")
    api_keys = _load("api_keys.json")
    catalog_objects = _load("catalog_objects.json")
    request_logs = _load("request_logs.json")

    def _log(status, api_key_id=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        request_logs.append({
            "id": "req_" + datetime.datetime.utcnow().strftime("%Y%m%d%H%M%S%f"),
            "endpoint": "get_catalog_object",
            "project_id": project_id,
            "api_key_id": api_key_id,
            "status": status,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now
        })
        _save("request_logs.json", request_logs)

    # --- Auth: active api_keys scoped to active project with allow_introspection
    proj = next((p for p in projects if p.get("id") == project_id), None)
    if not proj or proj.get("status") != "active":
        _log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Project is not active or does not exist.")

    usable_key = None
    for k in api_keys:
        if k.get("project_id") != project_id or k.get("status") != "active":
            continue
        perms = k.get("permissions") or {}
        if perms.get("allow_introspection") is True:
            usable_key = k
            break
    if not usable_key:
        _log("error", None, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key is authorized to introspect this project.")

    allowed = proj.get("allowed_schemas", None)
    if allowed is not None and schema_name not in allowed:
        _log("error", usable_key.get("id"), "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Schema is not visible under allowed_schemas.", schema_name=schema_name)

    if object_type == "column" and parent_object_id is None:
        _log("error", usable_key.get("id"), "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "parent_object_id is required when object_type is 'column'.")

    # Locate object by unique key (project_id, object_type, schema_name, object_name, parent_object_id)
    def _poid(row):
        return row.get("parent_object_id", None)

    found = None
    for o in catalog_objects:
        if o.get("project_id") != project_id:
            continue
        if o.get("object_type") != object_type:
            continue
        if o.get("schema_name") != schema_name:
            continue
        if o.get("object_name") != object_name:
            continue
        # parent_object_id must match (None matches None)
        if object_type == "column":
            if _poid(o) != parent_object_id:
                continue
        else:
            # for non-column, caller shouldn't need parent; treat mismatch if store has parent set (should be null by constraint)
            if parent_object_id is not None and _poid(o) != parent_object_id:
                continue
        found = o
        break

    if not found:
        _log("error", usable_key.get("id"), "NOT_FOUND")
        return _err("NOT_FOUND", "Catalog object not found.")

    if found.get("status") == "dropped" and not include_dropped:
        _log("error", usable_key.get("id"), "NOT_FOUND")
        return _err("NOT_FOUND", "Catalog object is dropped.", id=found.get("id"))

    # Update last_used_at for the key for observability
    usable_key["last_used_at"] = now
    usable_key["updated_at"] = now
    _save("api_keys.json", api_keys)

    _log("ok", usable_key.get("id"), None)
    return {"object": found}
